# Check vertex connectivity via Menger: max-flow between every pair
# Implement simple max flow (edge-disjoint paths on vertex-split graph)
from collections import defaultdict, deque

def vertex_connectivity(n, adj):
    # For each non-adjacent pair s,t compute local vertex connectivity using BFS-based max flow
    # Split each vertex v into v_in, v_out with capacity 1 between them
    # Build flow network
    def local_kappa(s, t):
        # nodes: for each v, in=2v, out=2v+1. Edge in->out cap 1 (except s,t: infinite)
        # For (u,v) edge: out_u -> in_v cap 1, out_v -> in_u cap 1
        N = 2*n
        cap = defaultdict(lambda: defaultdict(int))
        INF = 10**9
        for v in range(n):
            c = INF if v==s or v==t else 1
            cap[2*v][2*v+1] = c
        for u in range(n):
            for v in adj[u]:
                cap[2*u+1][2*v] = INF
        # BFS max flow (Edmonds-Karp)
        source = 2*s+1
        sink = 2*t
        flow = 0
        while True:
            parent = {source: None}
            q = deque([source])
            while q and sink not in parent:
                x = q.popleft()
                for y, c in cap[x].items():
                    if c > 0 and y not in parent:
                        parent[y] = x
                        q.append(y)
            if sink not in parent:
                break
            # find bottleneck
            path = []
            cur = sink
            bn = INF
            while parent[cur] is not None:
                p = parent[cur]
                bn = min(bn, cap[p][cur])
                path.append((p,cur))
                cur = p
            for p,c in path:
                cap[p][c] -= bn
                cap[c][p] += bn
            flow += bn
        return flow

    min_k = n
    for s in range(n):
        for t in range(s+1, n):
            if t in adj[s]: 
                continue  # skip adjacent
            k = local_kappa(s,t)
            if k < min_k:
                min_k = k
                if min_k < 4:
                    return min_k, (s,t)
    return min_k, None

